"""Corpus identity for collected model witnesses.

A corpus identity is ``(entry, recovered input values)``.  Model results,
bytes after a string NUL, transport arguments, object order and preparation
metadata never take part, while arrays, objects, booleans and integers keep
their JSON type identity (so empty arrays and empty objects differ).
"""


def freeze(value):
    """Canonical hashable form of a JSON value, preserving type identity."""
    if value is True:
        return ('b', True)
    if value is False:
        return ('b', False)
    if isinstance(value, bool):
        return ('b', value)
    if isinstance(value, int):
        return ('i', value)
    if isinstance(value, str):
        return ('s', value)
    if value is None:
        return ('n',)
    if isinstance(value, float):
        return ('f', value)
    if isinstance(value, dict):
        return ('o', tuple(sorted((key, freeze(item))
                                  for key, item in value.items())))
    if isinstance(value, (list, tuple)):
        return ('a', tuple(freeze(item) for item in value))
    return ('?', repr(value))


def make_hashable(obj):
    """Historic alias of :func:`freeze`."""
    return freeze(obj)


def recreate_structure(hashable):
    """Rebuild plain containers from :func:`freeze` output."""
    if isinstance(hashable, tuple) and hashable and hashable[0] == 'o':
        return {key: recreate_structure(val) for key, val in hashable[1]}
    if isinstance(hashable, tuple) and hashable and hashable[0] == 'a':
        return [recreate_structure(item) for item in hashable[1]]
    return hashable


def identity(entry, inputs):
    """Corpus identity of a recovered witness."""
    return (entry, freeze(inputs))
